algorithm PriceAverage
    define mutable price1 as integer <- 0;
    define mutable price2 as integer <- 0;
    define mutable sum as integer <- 0;
    read price1;
    read price2;
    sum <- price1 + price2;
    write sum;
endAlgorithm
